-- tasks completed up to the end of yesterday (D-1) in UTC.
latest_task AS (
  SELECT
    t.seller_id,
    t.completed_at AS last_call_made_at,
    t.disposition,
    t.remarks
  FROM `nushop.ob_tasks` AS t
  WHERE t.seller_id IN (SELECT seller_id FROM target_sellers)
    AND t.completed_at IS NOT NULL
    AND t.completed_at < TIMESTAMP(CURRENT_DATE('UTC'))  -- only data through D-1
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY t.seller_id
    ORDER BY t.completed_at DESC
  ) = 1
)

SELECT
  s.seller_id                  AS seller_id,
  DATE(lt.last_call_made_at)   AS last_call_made_date,
  lt.disposition               AS latest_disposition,
  lt.remarks                   AS remarks
FROM target_sellers AS s
LEFT JOIN latest_task AS lt
  ON lt.seller_id = s.seller_id
ORDER BY last_call_made_date DESC NULLS LAST;
